mapper.select:
SELECT NULL::bigint AS user_id,p.bsn_part_id AS part_id,p.prj_id AS project_id,NULL::bigint AS developer_id
    FROM mst.ptnr v LEFT JOIN prj.prj p ON p.cust_ptnr_id=v.ptnr_id AND p.use_yn='Y' WHERE v.ptnr_id=#{id}
    UNION SELECT NULL::bigint,d.bsn_part_id,p.prj_id,d.dev_id FROM mst.dev d
    LEFT JOIN asgn.asgn a ON a.dev_id=d.dev_id LEFT JOIN prj.prj p ON p.prj_id=a.prj_id AND p.use_yn='Y' WHERE d.vndr_ptnr_id=#{id}
